mapper.select:
SELECT a.LEDGER_ID, a.`QUESTION_ID`, a.`QUESTION_ID_1`, a.QUESTION_DSCR_1, a.`QUESTION_ID_2`, a.QUESTION_DSCR_2, a.QUESTION_CONTENT, a.QUESTION_OPINIONS, c.REFORM_SCHEME, c.MEMO FROM inspection.`inspection_question_ledger` a LEFT JOIN inspection.`inspection_reform_ledger` b ON a.`LEDGER_ID` = b.`LEDGER_ID` LEFT JOIN inspection.`inspection_reform_scheme` c ON b.`ID` = c.`REFORM_ID` WHERE 1 = 1
AND a.TASK_ID =#{params.TASK_ID}
ORDER BY a.`QUESTION_ID_1`, a.`QUESTION_ID_2`, a.`QUESTION_ID`, a.ADD_USERID, a.ADD_DATE DESC
